A;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA,yBAAyB;AACzB,gCAAgC,uCAAuC;AACvE,6BAA6B;AAC7B,uBAAuB;AACvB;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA,yBAAyB;AACzB;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA,mBAAmB;AACnB;AACA;AACA;AACA,wBAAwB;AACxB,eAAe;AACf;AACA;AACA;AACA;AACA,qBAAqB,uBAAuB;AAC5C;AACA;AACA;AACA;AACA,uCAAuC,sBAAsB;AAC7D;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA,iCAAiC;AACjC;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA,iCAAiC;AACjC;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA,4BAA4B,sCAAsC;AAClE;AACA;AACA;AACA;AACA;AACA;AACA;AACA,qBAAqB;AACrB;AACA;AACA;AACA;AACA;AACA,mBAAmB;AACnB;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;;;;;;;;;;;;;;ACjgBA;AAAA;AAAA;AAAA;AACA;AACA;AACA;AACA;AACA;AACA;AACA,SAAS,gCAAgC;AACzC;AACA,qBAAqB,sBAAsB;AAC3C;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA;AACA,eAAe;AACf;AACA,WAAW;AACX;AACA;AACA;AACA;AACA;AACA;AACA;;;;;;;;;;;;;;ACjCA;AAAA;AAAA;AAAA;AAAyF;AAC3B;AACL;;;AAGzD;AACyG;AACzG,gBAAgB,2GAAU;AAC1B,EAAE,gFAAM;AACR,EAAE,qFAAM;AACR,EAAE,8FAAe;AACjB;AACA;AACA;AACA;;AAEA;;AAEA;AACA,IAAI,KAAU,EAAE,YAiBf;AACD;AACe,gF;;;;;;;;;;;;ACtCf;AAAA;AAAA,wCAAwM,CAAgB,8OAAG,EAAC,C;;;;;;;;;;;;ACA5N;AAAA;AAAA;AAAA;AAAA;AAAA;;;;;;;;;;;;;ACAA;AAAA;AAAA;AAAA;AAA6F;AAC3B;AACL;;;AAG7D;AACyG;AACzG,gBAAgB,2GAAU;AAC1B,EAAE,oFAAM;AACR,EAAE,yFAAM;AACR,EAAE,kGAAe;AACjB;AACA;AACA;AACA;;AAEA;;AAEA;AACA,IAAI,KAAU,EAAE,YAiBf;AACD;AACe,gF;;;;;;;;;;;;ACtCf;AAAA;AAAA,wCAA4M,CAAgB,kPAAG,EAAC,C;;;;;;;;;;;;ACAhO;AAAA;AAAA;AAAA;AAAA;AAAA;;;;;;;;;;;;;ACAA;AAAA;AAAA;AAAA;AAAqG;AAC3B;AACL;;;AAGrE;AACyG;AACzG,gBAAgB,2GAAU;AAC1B,EAAE,4FAAM;AACR,EAAE,iGAAM;AACR,EAAE,0GAAe;AACjB;AACA;AACA;AACA;;AAEA;;AAEA;AACA,IAAI,KAAU,EAAE,YAiBf;AACD;AACe,gF;;;;;;;;;;;;ACtCf;AAAA;AAAA,wCAAoN,CAAgB,0PAAG,EAAC,C;;;;;;;;;;;;ACAxO;AAAA;AAAA;AAAA;AAAA;AAAA","file":"chunks/ceres-client-7.js","sourcesContent":["<template>\n    <div>\n\n\n        <div>\n            <div v-if=\"!basketItems.length > 0\">\n                <div class=\"h5 py-3\">{{ $translate(\"Ceres::Template.basketNoItems\") }}</div>\n            </div>\n            <transition-group name=\"list-transition\" tag=\"div\">\n                <template v-for=\"basketItem in basketItems\">\n                    <basket-list-item\n                        :key=\"basketItem.id\"\n                        :basket-item=\"basketItem\"\n                        :is-preview=\"isPreview\"\n                        :basket-details-data=\"basketDetailsData\"\n                    >\n                        <template #before-basket-item>\n                            <slot name=\"before-basket-item\"></slot>\n                        </template>\n                        <template #after-basket-item>\n                            <slot name=\"after-basket-item\"></slot>\n                        </template>\n                    </basket-list-item>\n                </template>\n            </transition-group>\n        </div>\n\n        <loading-animation v-if=\"!isBasketInitiallyLoaded\" class=\"d-table w-100\"></loading-animation>\n    </div>\n</template>\n\n<script>\nimport { mapState } from \"vuex\";\nimport BasketListItem from \"./BasketListItem.vue\";\n\nexport default {\n    name: \"basket-list\",\n    \n    components:\n    {\n        BasketListItem\n    },\n\n    props:\n    {\n        template:\n        {\n            type: String,\n            default: \"#vue-basket-list\"\n        },\n        basketDetailsData:\n        {\n            type: Array,\n            default: () => []\n        },\n        isPreview:\n        {\n            type: Boolean,\n            default: false\n        }\n    },\n\n    computed: mapState({\n        basketItems: state => state.basket.items,\n        isBasketInitiallyLoaded: state => state.basket.isBasketInitiallyLoaded\n    })\n}\n</script>\n","<template>\n    <div class=\"basket-list-item py-3\">\n        <slot name=\"before-basket-item\"></slot>\n\n        <div class=\"basket-item component-loading with-icon d-flex\" :class=\"{ 'sending is-loading': waiting, 'is-loading': isCheckoutReadonly }\">\n            <div class=\"image-container\">\n              <a :href=\"basketItem.variation.data | itemURL\">\n                <lazy-img\n                    picture-class=\"d-block mw-100 mh-100\"\n                    v-if=\"image\"\n                    :image-url=\"image\"\n                    :alt=\"altText\"\n                    :title=\"itemName\"\n                    data-testing=\"basket-item-img\">\n                </lazy-img>\n              </a>\n            </div>\n\n            <div class=\"meta-container-wrapper\">\n                <div class=\"meta-container-wrapper-inner\">\n                    <div class=\"meta-container\">\n                        <div class=\"position-relative w-100\">\n                            <a :href=\"basketItem.variation.data | itemURL\" class=\"item-name text-primary text-appearance small font-weight-bold text-break\" data-testing=\"basket-item-name\">\n                                {{ basketItem.variation.data | itemName }}\n                            </a>\n\n                            <div class=\"item-base-price small\">\n                                {{ unitPrice | currency }}\n                            </div>\n\n                            <item-bundle\n                                    :bundle-type=\"basketItem.variation.data.variation.bundleType\"\n                                    :bundle-components=\"basketItem.variation.data.bundleComponents\">\n                            </item-bundle>\n\n                            <div class=\"text-muted small\" v-if=\"!(basketItem.variation.data.unit.unitOfMeasurement === 'C62' && basketItem.variation.data.unit.content === 1) && basketItem.variation.data.variation.mayShowUnitPrice\">\n                                <div>\n                                    {{ basePrice }}\n                                </div>\n                                <div>\n                                    <strong>{{ $translate(\"Ceres::Template.basketContent\") }}: </strong>\n                                    {{ basketItem.variation.data.unit.content }} {{ basketItem.variation.data.unit.names.name }}\n                                </div>\n                            </div>\n\n                            <div class=\"small\" v-if=\"basketItem.inputLength > 0 || basketItem.inputWidth > 0\">\n                                <div>\n                                    <strong>{{ $translate(\"Ceres::Template.itemInput\") }} {{ basketItem | inputUnit(true)}}: </strong>\n                                    {{ basketItem | inputUnit }}\n                                </div>\n                            </div>\n\n                            <div class=\"small\">\n                                <div v-for=\"attribute in basketItem.variation.data.attributes\">\n                                    <strong>{{ attribute.attribute.names.name }}: </strong>\n                                    <span>{{ attribute.value.names.name }}</span>\n                                </div>\n                            </div>\n\n                            <div class=\"text-muted small\">\n                                <template v-for=\"propertyGroup in basketItem.variation.data.variationProperties\">\n                                    <div v-for=\"property in propertyGroup.properties\">\n                                        <strong v-if=\"propertyGroup.name\">{{ propertyGroup.name }}: </strong>\n                                        <span>{{ property.names.name }}</span>\n                                        <span v-if=\"property.cast === 'file'\">\n                                            <a :href=\"property.values.value | propertyFileUrl\" v-html=\"property.values.value\" target=\"_blank\"></a>\n                                        </span>\n                                        <template v-else-if=\"property.cast === 'multiSelection' && property.values[0] !== undefined\">\n                                            <ul class=\"pl-3\">\n                                                <li v-for=\"multiSelectProperty in property.values\">{{ multiSelectProperty.value }}</li>\n                                            </ul>\n                                        </template>\n                                        <span v-else v-html=\"property.values.value\"></span>\n                                    </div>\n                                </template>\n                            </div>\n                        </div>\n                    </div>\n\n                    <div class=\"basket-item-container-right\">\n                        <div class=\"qty-box-container\">\n                            <quantity-input\n                                    @quantity-change=\"updateQuantity\"\n                                    :value=\"basketItem.quantity\"\n                                    :waiting=\"isInputLocked || isCheckoutReadonly\"\n                                    :min=\"basketItem.variation.data.variation.minimumOrderQuantity\"\n                                    :max=\"basketItem.variation.data.variation.maximumOrderQuantity\"\n                                    :interval=\"basketItem.variation.data.variation.intervalOrderQuantity\">\n                            </quantity-input>\n                        </div>\n\n                        <div class=\"price-box text-right ml-2 mt-1\">\n                            <div class=\"item-total-price font-weight-bold text-nowrap\">{{ basketItem.quantity * unitPrice | currency(basketItem.variation.data.prices.default.currency) }}</div>\n\n                            <button\n                                class=\"btn btn-sm text-danger p-0\"\n                                :class=\"{ 'disabled': waiting || isBasketLoading || isCheckoutReadonly || waitingForDelete }\"\n                                @click=\"deleteItem\"\n                                data-testing=\"basket-item-delete\">\n                                {{ $translate(\"Ceres::Template.basketDelete\") }}\n                                <icon icon=\"trash-o\" class=\"default-float\" :loading=\"waitingForDelete\"></icon>\n                            </button>\n                        </div>\n                    </div>\n                </div>\n\n                <basket-set-component-list v-if=\"basketItem.setComponents\" :set-components=\"basketItem.setComponents\" :set-item=\"basketItem\"></basket-set-component-list>\n                \n                <order-property-value-list :basket-item=\"basketItem\"></order-property-value-list>\n\n                <div class=\"small\" v-if=\"showMoreInformation\">\n                    <template v-if=\"isDataFieldVisible('basket.item.item_id') && basketItem.variation.data.item.id\">\n                        <div class=\"mt-3\">\n                            <strong>{{ $translate(\"Ceres::Template.basketItemId\") }}:</strong>\n                            <span>{{ basketItem.variation.data.item.id }}</span>\n                        </div>\n                    </template>\n\n                    <template v-if=\"isDataFieldVisible('basket.item.customNumber')\">\n                        <div v-if=\"basketItem.variation.data.variation.number\">\n                            <strong>{{ $translate(\"Ceres::Template.basketItemNumber\") }}:</strong>\n                            <span>{{ basketItem.variation.data.variation.number }}</span>\n                        </div>\n                    </template>\n\n                    <template v-if=\"isDataFieldVisible('basket.item.availability')\">\n                        <div v-if=\"basketItem.variation.data.variation.availability && basketItem.variation.data.variation.availability.names.name\">\n                            <strong>{{ $translate(\"Ceres::Template.basketAvailability\") }}:</strong>\n                            <span>{{ basketItem.variation.data.variation.availability.names.name }}</span>\n                        </div>\n                    </template>\n\n                    <template v-if=\"isDataFieldVisible('basket.item.description_long')\">\n                        <p class=\"my-3\" v-if=\"basketItem.variation.data.texts.description\" v-html=\"basketItem.variation.data.texts.description\"></p>\n                    </template>\n\n                    <template v-if=\"isDataFieldVisible('basket.item.description_short')\">\n                        <p class=\"my-3\" v-if=\"basketItem.variation.data.texts.shortDescription\" v-html=\"basketItem.variation.data.texts.shortDescription\"></p>\n                    </template>\n                </div>\n\n                <label v-if=\"isMoreButtonVisible\"\n                    class=\"btn-collapse\"\n                    :class=\"{ 'collapsed': !showMoreInformation }\"\n                    @click=\"showMoreInformation = !showMoreInformation\"\n                    :data-show-more=\"$translate('Ceres::Template.basketShowMore')\"\n                    :data-show-less=\"$translate('Ceres::Template.basketShowLess')\">\n                </label>\n            </div>\n        </div>\n\n        <slot name=\"after-basket-item\"></slot>\n    </div>\n</template>\n\n<script>\nimport ExceptionMap from \"../../../exceptions/ExceptionMap\";\nimport TranslationService from \"../../../services/TranslationService\";\nimport {isDefined, isNullOrUndefined} from \"../../../helper/utils\";\nimport { mapState } from \"vuex\";\n\nconst NotificationService = require(\"../../../services/NotificationService\");\n\nimport BasketSetComponentList from \"./BasketSetComponentList.vue\";\nimport OrderPropertyValueList from \"../../item/OrderPropertyValueList.vue\"\n\nexport default {\n    name: \"basket-list-item\",\n    \n    components:\n    {\n        BasketSetComponentList,\n        OrderPropertyValueList\n    },\n\n    props:\n    {\n        template:\n        {\n            type: String,\n            default: \"#vue-basket-list-item\"\n        },\n        basketItem: Object,\n        basketDetailsData:\n        {\n            type: Array,\n            default: () => []\n        },\n        isPreview:\n        {\n            type: Boolean,\n            default: false\n        }\n    },\n\n    data()\n    {\n        return {\n            waiting: false,\n            waitingForDelete: false,\n            itemCondition: \"\",\n            showMoreInformation: false\n        };\n    },\n\n    computed:\n    {\n        image()\n        {\n            const itemImages = this.$options.filters.itemImages(this.basketItem.variation.data.images, \"urlPreview\");\n\n            return this.$options.filters.itemImage(itemImages);\n        },\n\n        altText()\n        {\n            const images = this.$options.filters.itemImages(this.basketItem.variation.data.images, \"urlPreview\");\n            const altText =  this.$options.filters.itemImageAlternativeText(images);\n\n            if (altText)\n            {\n                return altText;\n            }\n\n            return this.itemName;\n        },\n\n        itemName()\n        {\n            return this.$options.filters.itemName(this.basketItem.variation.data);\n        },\n\n        isInputLocked()\n        {\n            return this.waiting || this.isBasketLoading;\n        },\n\n        propertySurchargeSum()\n        {\n            let sum = 0;\n\n            for (const property of this.basketItem.basketItemOrderParams)\n            {\n                sum += this.$options.filters.propertySurcharge(this.basketItem.variation.data.properties, property.propertyId);\n            }\n\n            return sum;\n        },\n\n        unitPrice()\n        {\n            let setComponentsParamSurcharge = 0;\n            if(isDefined(this.basketItem.setComponents))\n            {\n                setComponentsParamSurcharge = this.basketItem.setComponents\n                    .map(component => component.quantity * component.attributeTotalMarkup)\n                    .reduce((sum, i) => sum + i, 0);\n            }\n            return this.basketItem.price + setComponentsParamSurcharge;\n        },\n\n        basePrice()\n        {\n            // if the 'AfterBasketItemUpdate' event contains a new base price for the item, return it\n            if (!isNullOrUndefined(this.basketItem.updatedBasePrice)) \n            {\n                return this.basketItem.updatedBasePrice;\n            }\n\n            if (!isNullOrUndefined(this.basketItem.variation.data.prices.specialOffer))\n            {\n                return this.basketItem.variation.data.prices.specialOffer.basePrice;\n            }\n\n            if (!isNullOrUndefined(this.basketItem.variation.data.prices.graduatedPrices))\n            {\n              let calculatedPrice = null;\n              this.basketItem.variation.data.prices.graduatedPrices.forEach(price =>\n              {\n                  if(isNullOrUndefined(calculatedPrice) && this.basketItem.quantity >= price.minimumOrderQuantity) {\n                    calculatedPrice = price;\n                  }\n                  else if(this.basketItem.quantity >= price.minimumOrderQuantity && price.minimumOrderQuantity >= calculatedPrice.minimumOrderQuantity ) {\n                    calculatedPrice = price;\n                  }\n              });\n\n              if (!isNullOrUndefined(calculatedPrice)) {\n                return calculatedPrice.basePrice;\n              }\n            }\n\n            return this.basketItem.variation.data.prices.default.basePrice;\n        },\n\n        // eslint-disable-next-line complexity\n        isMoreButtonVisible()\n        {\n            return this.isDataFieldVisible(\"basket.item.item_id\") && this.basketItem.variation.data.item.id ||\n                   this.isDataFieldVisible(\"basket.item.customNumber\") && this.basketItem.variation.data.variation.number ||\n                   this.isDataFieldVisible(\"basket.item.availability\") && this.basketItem.variation.data.variation.availability.names.name ||\n                   this.isDataFieldVisible(\"basket.item.description_long\") && this.basketItem.variation.data.texts.description ||\n                   this.isDataFieldVisible(\"basket.item.description_short\") && this.basketItem.variation.data.texts.shortDescription;\n        },\n\n        ...mapState({\n            isBasketLoading: state => state.basket.isBasketLoading,\n            isCheckoutReadonly: state => state.checkout.readOnly,\n            showNetPrice: state => state.basket.showNetPrices\n        })\n    },\n\n    methods: {\n\n        /**\n         * Delete item from basket\n         */\n        deleteItem()\n        {\n            if (!this.waiting && !this.waitingForDelete && !this.isBasketLoading)\n            {\n                this.waitingForDelete = true;\n\n                this.$store.dispatch(\"removeBasketItem\", this.basketItem.id).then(\n                    response =>\n                    {\n                        document.dispatchEvent(new CustomEvent(\"afterBasketItemRemoved\", { detail: this.basketItem }));\n                        this.waitingForDelete = false;\n                    },\n                    error =>\n                    {\n                        this.waitingForDelete = false;\n                    });\n            }\n        },\n\n        /**\n         * Update item quantity in basket\n         * @param quantity\n         */\n        updateQuantity(quantity)\n        {\n            if (this.basketItem.quantity !== quantity)\n            {\n                this.waiting = true;\n\n                const origQty = this.basketItem.quantity;\n\n                this.$store.dispatch(\"updateBasketItemQuantity\", { id: this.basketItem.id, variationId: this.basketItem.variation.id, quantity: quantity }).then(\n                    response =>\n                    {\n                        document.dispatchEvent(new CustomEvent(\"afterBasketItemQuantityUpdated\", { detail: this.basketItem }));\n                        this.waiting = false;\n                    },\n                    error =>\n                    {\n                        this.basketItem.quantity = origQty;\n\n                        if (this.isPreview)\n                        {\n                            this.$store.dispatch(\n                                \"addBasketNotification\",\n                                {\n                                    type: \"error\",\n                                    message: TranslationService.translate(\n                                        \"Ceres::Template.\" + ExceptionMap.get(error.data.exceptionCode.toString()),\n                                        error.data.placeholder\n                                    )\n                                }\n                            );\n                        }\n                        else\n                        {\n                            NotificationService.error(\n                                TranslationService.translate(\n                                    \"Ceres::Template.\" + ExceptionMap.get(error.data.exceptionCode.toString()),\n                                    error.data.placeholder\n                                )\n                            ).closeAfter(5000);\n                        }\n\n                        this.waiting = false;\n                    });\n            }\n        },\n\n        isDataFieldVisible(value)\n        {\n            return this.basketDetailsData.includes(value);\n        }\n    }\n}\n</script>\n","<template>\n    <div v-if=\"setComponents.length > 0\" class=\"set-data small\">\n        <div class=\"mb-2\"><strong>{{ $translate(\"Ceres::Template.itemSetContent\") }}</strong></div>\n        <template v-for=\"setComponent in setComponents\">\n            <set-component-item :variation=\"setComponent.variation.data\" :quantity=\"setComponent.quantity\" :order-properties=\"setComponent.basketItemOrderParams\" :rebate=\"setItem.variation.data.item.rebate\"></set-component-item>\n        </template>\n    </div>\n</template>\n\n<script>\nimport SetComponentItem from \"./SetComponentItem.vue\"\n\nexport default {\n    name: \"basket-set-component-list\",\n\n    components: {\n        SetComponentItem\n    },\n\n    props: {\n        setComponents: {\n            type: Array,\n            default: () => []\n        },\n        setItem: Object\n    }\n}\n</script>\n","var render = function() {\n  var _vm = this\n  var _h = _vm.$createElement\n  var _c = _vm._self._c || _h\n  return _c(\n    \"div\",\n    [\n      _c(\n        \"div\",\n        [\n          !_vm.basketItems.length > 0\n            ? _c(\"div\", [\n                _c(\"div\", { staticClass: \"h5 py-3\" }, [\n                  _vm._v(\n                    _vm._s(_vm.$translate(\"Ceres::Template.basketNoItems\"))\n                  )\n                ])\n              ])\n            : _vm._e(),\n          _vm._v(\" \"),\n          _c(\n            \"transition-group\",\n            { attrs: { name: \"list-transition\", tag: \"div\" } },\n            [\n              _vm._l(_vm.basketItems, function(basketItem) {\n                return [\n                  _c(\"basket-list-item\", {\n                    key: basketItem.id,\n                    attrs: {\n                      \"basket-item\": basketItem,\n                      \"is-preview\": _vm.isPreview,\n                      \"basket-details-data\": _vm.basketDetailsData\n                    },\n                 